 62	    /**
 63	     * How much power the planet wants: the deficit it is already in, or the one its next production
 64	     * upgrade would create, whichever is larger. Zero when the balance covers the next step.
 65	     *
 66	     * The magnitude is public because a planet that cannot buy the capacity has one other route --
 67	     * the yard -- and how many power units that route needs is this question's answer, not a second
 68	     * calculation over the same host numbers.
 69	     */
 70	    public function shortfall(PlanetService $planet): float
 71	    {
 72	        $energy = (float) $planet->energy()->get();
 73	        $deficit = -$energy;
 74	
 75	        // A consumer is any production object whose next level draws more than it makes, so the
 76	        // planet is short when one of those upgrades would land it below zero.
 77	        foreach (ObjectService::getGameObjectsWithProduction() as $object) {
 78	            $gain = $this->energyGainOfNextLevel($planet, $object->machine_name);
 79	
 80	            if ($gain < 0.0) {
 81	                $deficit = max($deficit, -($energy + $gain));
 82	            }
 83	        }
 84	
 85	        return max(0.0, $deficit);
 86	    }
